// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract DatabaseDriver {
    enum Role { NONE, READER, WRITER, ADMIN }

    struct Record {
        bytes32 key;
        uint256 value;
        uint64 timestamp;
        uint64 version;
        address owner;
    }

    struct Pagination {
        uint128 offset;
        uint128 limit;
    }

    mapping(address => Role) public roles;
    mapping(bytes32 => Record) public records;
    mapping(address => uint256) public queryCredits;

    uint256 public totalRecords;
    uint256 constant MAX_BATCH_SIZE = 100;
    uint256 constant CREDIT_COST_PER_RECORD = 10;

    address public immutable owner;

    event RecordWritten(bytes32 indexed key, uint256 value, address indexed writer);
    event CreditsAllocated(address indexed user, uint256 amount);
    event BatchQueryExecuted(address indexed user, uint256 recordCount, uint256 creditsCost);

    modifier onlyRole(Role _minRole) {
        require(uint8(roles[msg.sender]) >= uint8(_minRole), "Insufficient role");
        _;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor() {
        owner = msg.sender;
        roles[msg.sender] = Role.ADMIN;
        queryCredits[msg.sender] = type(uint256).max;
    }

    function grantRole(address _user, Role _role) external onlyRole(Role.ADMIN) {
        require(_role != Role.ADMIN || msg.sender == owner, "Only owner grants admin");
        roles[_user] = _role;
    }

    function allocateCredits(address _user, uint256 _amount) external onlyRole(Role.ADMIN) {
        queryCredits[_user] += _amount;
        emit CreditsAllocated(_user, _amount);
    }

    function writeRecord(bytes32 _key, uint256 _value) external onlyRole(Role.WRITER) {
        Record storage rec = records[_key];
        if (rec.owner == address(0)) {
            totalRecords++;
            rec.owner = msg.sender;
        }
        rec.key = _key;
        rec.value = _value;
        rec.timestamp = uint64(block.timestamp);
        rec.version++;
        emit RecordWritten(_key, _value, msg.sender);
    }

    function readRecord(bytes32 _key) external view onlyRole(Role.READER) returns (Record memory) {
        return records[_key];
    }

    /// @notice Execute a batch query with pagination
    /// @param _keys Array of record keys to query
    /// @param _pagination Offset and limit for result windowing
    /// @return results The queried records within the pagination window
    function batchQuery(
        bytes32[] calldata _keys,
        Pagination calldata _pagination
    ) external onlyRole(Role.READER) returns (Record[] memory results) {
        uint256 totalKeys = _keys.length;
        require(totalKeys <= MAX_BATCH_SIZE, "Batch too large");

        // Calculate the effective window
        uint256 offset = uint256(_pagination.offset);
        uint256 limit = uint256(_pagination.limit);

        // Determine how many records fall within our window
        uint256 end = offset + limit;

        // Bounds check: if offset exceeds total keys, return empty
        if (offset >= totalKeys) {
            return new Record[](0);
        }

        // Cap end to totalKeys
        if (end > totalKeys) {
            end = totalKeys;
        }

        uint256 resultCount = end - offset;

        // Calculate credit cost for this query
        // Cost = resultCount * CREDIT_COST_PER_RECORD
        uint256 creditsCost = _computeCreditsCost(resultCount, _pagination);
        require(queryCredits[msg.sender] >= creditsCost, "Insufficient credits");
        queryCredits[msg.sender] -= creditsCost;

        results = new Record[](resultCount);
        for (uint256 i = 0; i < resultCount; i++) {
            results[i] = records[_keys[offset + i]];
        }

        emit BatchQueryExecuted(msg.sender, resultCount, creditsCost);
        return results;
    }

    /// @dev Internal cost computation considering pagination complexity
    /// @param _count Number of records being returned
    /// @param _pagination The pagination parameters for complexity weighting
    function _computeCreditsCost(
        uint256 _count,
        Pagination calldata _pagination
    ) internal pure returns (uint256) {
        // Base cost per record
        uint256 baseCost = _count * CREDIT_COST_PER_RECORD;

        // Complexity multiplier: queries with high offset cost more
        // due to internal index traversal simulation
        // Multiplier is 1 + (offset * limit) / (2^128)
        // This rewards small, focused queries
        uint256 complexityNumerator = uint256(_pagination.offset) * uint256(_pagination.limit);
        uint256 complexityDivisor = 2**128;

        // Total cost = baseCost * (1 + complexityNumerator / complexityDivisor)
        // = baseCost + (baseCost * complexityNumerator) / complexityDivisor
        uint256 additionalCost = (baseCost * complexityNumerator) / complexityDivisor;

        return baseCost + additionalCost;
    }

    function getCredits(address _user) external view returns (uint256) {
        return queryCredits[_user];
    }

    function getRole(address _user) external view returns (Role) {
        return roles[_user];
    }
}
